        "text": "План и запись ЕГРН: План ТП-41 содержит ошибочную характеристику: номер помещения 18 вместо 81. Сведения в ЕГРН воспроизведены точно по этому плану; регистратор не переставлял цифры.\n\nКомплект исправления ТП-41: Надлежащий исправленный план и подтверждающие документы поступили {{received}}. Необходимые сведения имеются полностью; зарегистрированные права и законные интересы третьих лиц не меняются."
