        "text": "Покупка и первое обращение: Товар партии М-8 куплен {{purchase}}. Жалоба основана на принятии даты изготовления за срок годности. Данных об иных недостатках в первом обращении нет.\n\nПолная маркировка партии М-8: Изготовлено {{manufactured}}. Годен до {{expiry}}. Названия полей хорошо читаемы; маркировка именно на упаковке из обращения."
