        "text": "Статья 10 Закона РФ № 2300-1 требует необходимой и достоверной информации о товаре, включая предусмотренные сведения о сроке годности и условиях использования. Дата изготовления не тождественна последнему допустимому дню использования. Из того, что срок по маркировке ещё не истёк, не следует вывод об отсутствии любых иных недостатков или нарушений хранения."
