        "text": "Накладная С-41: Перевозка {{observed}}: саженцы С-41, 180 единиц, из установленной зоны в питомник-получатель П-8. Условия необходимости сертификата подтверждены профильным органом.\n\nПроверенная электронная выписка: Карантинный сертификат ЭК-41 на С-41, 180 единиц, маршрут и получатель П-8 совпадают. Электронная подпись проверена; действительность документа на момент вывоза подтверждена."
