        "text": "Статья 21 закона № 206-ФЗ связывает карантинный сертификат с вывозом из установленной карантинной фитосанитарной зоны, введённым режимом и временными ограничениями, а также соответствующей подкарантинной продукцией. Сертификат имеет форму электронного документа с усиленной квалифицированной электронной подписью. Наличие требования проверяется по совокупности условий, а не по одному слову «рассада». Протокол лаборатории и сертификат имеют разное назначение."
