    "title": "Лицензия организации и документы работника · проверяемые материалы",
    "publisher": "Авторский пакет вымышленного дела",
    "url": "https://www.consultant.ru/document/cons_doc_LAW_491941/606f2d2c5965313c669095d80be9e71c0617a8c3/",
