        "id": "material",
        "label": "Материалы для сопоставления",
        "text": "Решение Р-63: Взыскана сумма по гражданскому спору. Решение вступило в силу; отдельный график исполнения судом пока не утверждён.\n\nОбращение и предложенный график: Мария предлагает ежемесячные платежи и прикладывает сведения о временном снижении дохода. Просит объяснить, кто может рассмотреть рассрочку; долг по существу не отрицает."
