        "text": "Судебный приказ СП-41: Мировой судья вынес приказ о взыскании денежной суммы. Рассмотрения иска с исследованием возражений сторон не проводилось.\n\nПисьмо в администрацию: Илья требует, чтобы администрация отменила СП-41. Возражения в суд ещё не направлял; считает муниципальный талон подтверждением их подачи."
