        "text": "Индивидуальный полис ИС-11: В поле «страхователь» указана Мария. Премия уплачена страховщику; страхование обеспечивает потребительский кредит. Это не включение в договор, где страхователем выступает банк.\n\nПодтверждение получения отказа: Страховщик получил подписанное заявление {{recipientReceived}} на двадцатый календарный день после заключения. Отсутствие событий с признаками страхового случая подтверждено. Более раннее письмо в банк получено {{received}}."
