        "text": "Подпункт «б» пункта 27 предусматривает ограничения размещения предметов на путях эвакуации; допустимость предусмотренного в норме оборудования связана с соблюдением геометрических параметров пути. Условия данного дела прямо фиксируют коробки и тележки, блокирующие проход, а не разрешённое проектом оборудование с сохранёнными параметрами. Открывающаяся дверь не устраняет препятствие в коридоре."
