        "id": "norm",
        "label": "Норма и пределы вывода",
        "text": "Статья 5 закона № 59-ФЗ предоставляет право знакомиться с материалами рассмотрения обращения, если это не затрагивает права и законные интересы других лиц и материалы не содержат защищаемой законом тайны. Наличие отдельного защищённого приложения не превращает все открытые материалы в секретные. В учебном деле допустимость ознакомления определяется составом каждого документа; иных законных оснований раскрывать данные третьего лица не задано."
