        "label": "Материалы для сопоставления",
        "text": "Журнал пользователя: Черновик создан {{observed}} и оставался в статусе «не отправлен». До нажатия кнопки у органа не было поступившего обращения.\n\nКвитанция К-38: После отправки {{received}} официальный сервис подтвердил поступление органу. Идентификатор обращения О-381; время предыдущего черновика отдельно обозначено."
